with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'علم المناخ التطبيقي والإحصاء المناخي','الإحصاء المناخي والفترات المرجعية والاتجاهات والقيم المتطرفة والتذبذبات والمناخات الإقليمية والأطالس.',36,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأسس والإحصاء المناخي',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التطرفات والتطبيقات الإقليمية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('climate-system-classification','تصنيف المناخ والأنظمة المناخية','مبادئ تصنيف الأقاليم المناخية ومحدداتها.','{"blocks":[{"type":"text","text":"يتناول الدرس تصنيف المناخ والأنظمة المناخية ضمن التحليل الإحصائي والمكاني للمناخ وتطبيقاته الإقليمية."},{"type":"text","text":"الموضوع الرئيس: مبادئ تصنيف الأقاليم المناخية ومحدداتها.، ويجب تحديد الفترة المرجعية والمقياس المكاني والمتغير المدروس."},{"type":"text","text":"تبدأ الدراسة بتحديد مصادر البيانات والمحطات والفترة الزمنية ومدى اكتمال السجلات."},{"type":"text","text":"تطبق فحوص التجانس والجودة وتراجع التغيرات في الأجهزة والمواقع والبيئة المحيطة بالمحطة."},{"type":"text","text":"تختار المقاييس الإحصائية المناسبة لطبيعة التوزيع والسؤال العلمي، مع توثيق الافتراضات."},{"type":"text","text":"تراعى الموسمية والارتباط الزمني والمكاني عند اختبار الاتجاهات أو مقارنة الفترات."},{"type":"text","text":"تستخدم الخرائط والتحليل المكاني لفهم الفروق الإقليمية وعدم تعميم خصائص موقع واحد على منطقة كاملة."},{"type":"text","text":"تقارن النتائج بفترات مرجعية أو مصادر مستقلة، وتوضح حساسية النتائج لاختيار الفترة والطريقة."},{"type":"text","text":"تعرض فترات الثقة وعدم اليقين والقيود، خصوصاً عند تحليل السجلات القصيرة أو القيم النادرة."},{"type":"text","text":"تترجم المخرجات إلى جداول وخرائط ومؤشرات قابلة للاستخدام في التخطيط وإدارة المخاطر."},{"type":"text","text":"مثال تطبيقي: مقارنة توزيع درجات الحرارة أو الهطول بين فترتين متجانستين مع عرض تغير المتوسط والتطرفات مكانياً."},{"type":"callout","text":"الخلاصة: التحليل المناخي الرصين يعتمد على سجل متجانس ومنهج إحصائي ملائم وتفسير إقليمي حذر."}]}',3560,60,'["اختيار البيانات والفترة المرجعية","تطبيق التحليل الإحصائي أو المناخي المناسب","تفسير النتائج مكانياً وزمنياً"]','الأسس والإحصاء المناخي'),
('climate-normals-and-reference-periods','المعدلات المناخية والفترات المرجعية','حساب المعدلات والفترات القياسية وتفسيرها.','{"blocks":[{"type":"text","text":"يتناول الدرس المعدلات المناخية والفترات المرجعية ضمن التحليل الإحصائي والمكاني للمناخ وتطبيقاته الإقليمية."},{"type":"text","text":"الموضوع الرئيس: حساب المعدلات والفترات القياسية وتفسيرها.، ويجب تحديد الفترة المرجعية والمقياس المكاني والمتغير المدروس."},{"type":"text","text":"تبدأ الدراسة بتحديد مصادر البيانات والمحطات والفترة الزمنية ومدى اكتمال السجلات."},{"type":"text","text":"تطبق فحوص التجانس والجودة وتراجع التغيرات في الأجهزة والمواقع والبيئة المحيطة بالمحطة."},{"type":"text","text":"تختار المقاييس الإحصائية المناسبة لطبيعة التوزيع والسؤال العلمي، مع توثيق الافتراضات."},{"type":"text","text":"تراعى الموسمية والارتباط الزمني والمكاني عند اختبار الاتجاهات أو مقارنة الفترات."},{"type":"text","text":"تستخدم الخرائط والتحليل المكاني لفهم الفروق الإقليمية وعدم تعميم خصائص موقع واحد على منطقة كاملة."},{"type":"text","text":"تقارن النتائج بفترات مرجعية أو مصادر مستقلة، وتوضح حساسية النتائج لاختيار الفترة والطريقة."},{"type":"text","text":"تعرض فترات الثقة وعدم اليقين والقيود، خصوصاً عند تحليل السجلات القصيرة أو القيم النادرة."},{"type":"text","text":"تترجم المخرجات إلى جداول وخرائط ومؤشرات قابلة للاستخدام في التخطيط وإدارة المخاطر."},{"type":"text","text":"مثال تطبيقي: مقارنة توزيع درجات الحرارة أو الهطول بين فترتين متجانستين مع عرض تغير المتوسط والتطرفات مكانياً."},{"type":"callout","text":"الخلاصة: التحليل المناخي الرصين يعتمد على سجل متجانس ومنهج إحصائي ملائم وتفسير إقليمي حذر."}]}',3570,60,'["اختيار البيانات والفترة المرجعية","تطبيق التحليل الإحصائي أو المناخي المناسب","تفسير النتائج مكانياً وزمنياً"]','الأسس والإحصاء المناخي'),
